INSERT INTO `recipes` (`id`, `title`, `description`, `user_id`, `flavor_tags`, `cuisine_tags`, `time_minutes`, `difficulty`, `ingredients_required`, `steps`, `nutrition_summary`, `video_tutorials`, `is_public`, `created_at`) VALUES
	(1, '晨间轻食-50道精选菜谱', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '[]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 36, "ingredientName": "芦笋"}, {"unit": "g", "quantity": 180.0, "categoryId": 2, "ingredientId": 54, "ingredientName": "牛肉"}]', '["准备食材：洋葱、黄瓜、土豆、胡萝卜，清洗后按常规切配。", "热锅少油，先下耐炒食材翻炒 2-3 分钟，再加入其余食材。", "按个人口味加入基础调味（盐、酱油等），中火翻炒或炖煮至熟。", "根据早餐场景控制分量，出锅前可加葱花提升风味。"]', '{"protein_estimate": 33.9, "calories_estimate": 469.0}', '{"douyin": "https://www.douyin.com/search/%E6%99%A8%E9%97%B4%E8%BD%BB%E9%A3%9F-50%E9%81%93%E7%B2%BE%E9%80%89%E8%8F%9C%E8%B0%B1+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 11:36:59'),
	(2, '温暖晚餐-50道精选菜谱', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '[]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["准备食材：白菜、菠菜、洋葱、黄瓜，清洗后按常规切配。", "热锅少油，先下耐炒食材翻炒 2-3 分钟，再加入其余食材。", "按个人口味加入基础调味（盐、酱油等），中火翻炒或炖煮至熟。", "根据晚餐场景控制分量，出锅前可加葱花提升风味。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B8%A9%E6%9A%96%E6%99%9A%E9%A4%90-50%E9%81%93%E7%B2%BE%E9%80%89%E8%8F%9C%E8%B0%B1+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 11:45:02'),
	(3, '湘味素炒三鲜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "咸鲜", "清爽", "微酸"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["白菜、菠菜择洗干净，白菜切段，菠菜切长段；洋葱切丝；胡萝卜、黄瓜、土豆、南瓜均切薄片或细条，备用", "热锅凉油，下洋葱丝爆香，加少许干辣椒段和蒜末炝锅，激出湘式香辣味", "先下胡萝卜、土豆、南瓜片中火煸炒至边缘微透明，再加入白菜、黄瓜、菠菜快速翻炒，保持蔬菜脆嫩", "淋入1勺生抽、半勺香醋、适量盐和白胡椒粉，翻匀出锅，装盘即可"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E7%B4%A0%E7%82%92%E4%B8%89%E9%B2%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 11:51:54'),
