	(8, '湘味蒸茄拌菠菜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "清爽", "咸鲜", "微麻"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["茄子洗净去皮切长条，上锅蒸12分钟至软糯；菠菜焯水30秒捞出沥干切段", "洋葱切细丝，黄瓜切细条，与菠菜、蒸茄一同放入大碗", "热锅少油，下蒜末、干辣椒段（湖南偏好）爆香，加少许生抽、香醋、白胡椒粉和少量盐调成湘式凉拌汁", "将热汁淋入蔬菜中，快速拌匀，静置2分钟入味即可装盘"]', '{"protein_estimate": 10.1, "calories_estimate": 238.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E8%92%B8%E8%8C%84%E6%8B%8C%E8%8F%A0%E8%8F%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 12:50:46'),
	(9, '湘味素炒三鲜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "鲜咸", "爽脆", "微酸"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["洋葱切丝、胡萝卜切细丝、白菜切段，菠菜择洗干净备用；", "热锅冷油，下洋葱丝爆香至微透明，加少许剁椒（湖南特色）激发辣香；", "转中火，先下胡萝卜丝煸炒1分钟至断生，再放入白菜段和菠菜，快速翻炒至蔬菜变软但保持翠绿；", "沿锅边淋入1勺生抽、半勺香醋提鲜增香，撒少量白胡椒粉，翻匀即出锅；", "装盘后可点缀少许葱花，突出湘菜明快风味；", "全程控制在8分钟内，契合早餐高效需求。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E7%B4%A0%E7%82%92%E4%B8%89%E9%B2%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:48:26'),
	(10, '湘味清炒时蔬', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "鲜咸", "爽脆", "微酸"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["洋葱切丝、胡萝卜切细丝、白菜切段、菠菜择洗干净，黄瓜切薄片备用；", "热锅冷油，下洋葱丝爆香至微透明，加半勺湖南剁椒激发辣香；", "转中火，先下胡萝卜丝和黄瓜片煸炒1分钟，再放入白菜段与菠菜，快速翻炒至断生仍保持翠绿脆嫩；", "沿锅边淋入1勺生抽、半勺香醋，撒少许白胡椒粉和细盐调味，翻匀即出锅；", "装盘后可点缀新鲜紫苏叶（湖南早餐常用），突出地域风味；", "全程控制在6分钟内，契合早餐快捷营养需求。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E6%B8%85%E7%82%92%E6%97%B6%E8%94%AC+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:48:31'),
	(11, '湘味南瓜胡萝卜粥', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香甜", "软糯", "微辣", "暖胃"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["南瓜去皮切小块，胡萝卜擦丝，洋葱切细末备用；", "锅中加水烧开，放入南瓜块和胡萝卜丝，中火煮15分钟至南瓜软烂；", "转小火，用勺背将南瓜压成泥，加入适量大米（用户未提供但早餐粥必备，默认微量使用）同煮至浓稠；", "另起小锅热油，爆香洋葱末至金黄微焦，加半勺湖南剁椒炒出红油，淋入粥中搅匀；", "调入少许生抽提鲜、白胡椒粉增暖意，尝味后补盐；", "盛碗后撒葱花点缀，温热食用，契合湖南人早餐重暖、微辣、饱腹需求。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E5%8D%97%E7%93%9C%E8%83%A1%E8%90%9D%E5%8D%9C%E7%B2%A5+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:48:37'),
	(12, '湘味南瓜胡萝卜粥', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香甜", "软糯", "微辣", "暖胃"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["南瓜去皮切小块，胡萝卜擦丝，洋葱切末，菠菜洗净焯水后挤干切碎；", "锅中加适量清水，放入南瓜块和胡萝卜丝，大火煮沸后转小火熬煮15分钟至南瓜软烂、汤汁微稠；", "加入洋葱末同煮3分钟激发辛香，再倒入菠菜碎搅匀；", "调入半勺生抽、少许白胡椒粉和微量湖南剁椒（提味不呛辣），继续煮2分钟；", "关火前淋几滴香油，撒少许葱花增香；", "全程约25分钟，温热软糯，契合湖南人早餐重暖胃、喜微辛的饮食习惯。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E5%8D%97%E7%93%9C%E8%83%A1%E8%90%9D%E5%8D%9C%E7%B2%A5+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:48:40'),
	(13, '湘味南瓜小米粥', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香甜", "软糯", "微辣", "暖胃"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["南瓜去皮切小块，胡萝卜擦丝，洋葱切细末备用；", "锅中加水烧开，放入南瓜块、胡萝卜丝及少量小米（早餐主食基础，微量默认添加），中火煮20分钟至浓稠软烂；", "用勺背将南瓜压碎融入粥中，使口感绵密；", "另起小锅热少许油，爆香洋葱末至微金黄，加入半勺湖南剁椒炒出红油，迅速淋入粥中搅匀；", "调入少许生抽提鲜、白胡椒粉增温、细盐调味，避免过咸；", "盛碗后撒新鲜葱花，趁热食用，契合湖南人早餐重暖、微辣、快简的饮食习惯。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E5%8D%97%E7%93%9C%E5%B0%8F%E7%B1%B3%E7%B2%A5+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:48:43'),
	(14, '湘味洋葱胡萝卜煎饼', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "酥脆", "微甜", "暖胃"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["胡萝卜擦细丝，洋葱切碎末，白菜切极细丝并用少许盐腌5分钟挤干水分；", "将所有蔬菜混合，加入适量面粉（早餐主食基础，微量默认添加）和1个鸡蛋调成浓稠面糊，加半勺湖南剁椒、少许白胡椒粉和葱花拌匀；", "平底锅烧热刷薄油，舀一勺面糊摊成圆饼，中小火煎至底面金黄定型后翻面；", "继续煎至两面酥脆微焦，内部熟透无生粉感；", "出锅稍晾不烫口，配一小碟香醋蘸食，突出湘式早餐的辛香开胃；", "全程约12分钟，无花生、高纤维低脂，契合湖南人早餐喜煎香重口味偏好。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E6%B4%8B%E8%91%B1%E8%83%A1%E8%90%9D%E5%8D%9C%E7%85%8E%E9%A5%BC+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:48:50'),
	(15, '湘味蒸茄拌菠菜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "清爽", "咸鲜", "微麻"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["茄子洗净去皮切长条，上锅蒸12分钟至软糯；菠菜焯水30秒捞出过凉挤干水分", "洋葱切细丝，黄瓜切细丝；蒸好的茄子稍压散，与菠菜、洋葱丝、黄瓜丝混合", "热锅少油，下蒜末、小米辣（可选干椒碎）和少许花椒爆香，淋入蒸鱼豉油和少量生抽调成湘式辣汁", "将辣汁均匀浇在蔬菜上，撒白胡椒粉和葱花，拌匀即可装盘"]', '{"protein_estimate": 10.1, "calories_estimate": 238.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E8%92%B8%E8%8C%84%E6%8B%8C%E8%8F%A0%E8%8F%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 13:51:54'),
