	(17, '湘味素炒三鲜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["香辣", "酱香", "咸鲜", "爽脆"]', '["湘菜", "粤菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 25, "ingredientName": "南瓜"}]', '["洋葱切丝、胡萝卜切薄片、黄瓜切菱形片，土豆去皮切细丝后泡水去淀粉；", "热锅凉油，下姜末、干辣椒段（湖南偏好）爆香，加洋葱丝中火煸至透明微焦；", "转大火，依次下胡萝卜片、土豆丝、黄瓜片快速翻炒1分钟，保持脆感；", "淋入1勺生抽、半勺老抽、少许糖和盐调味，撒葱花翻匀出锅；", "可选增香：起锅前滴几滴香醋提味，符合湘菜‘辣得鲜活、香得醇厚’特点。"]', '{"protein_estimate": 10.1, "calories_estimate": 239.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E7%B4%A0%E7%82%92%E4%B8%89%E9%B2%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 14:08:41'),
