	(24, '湘味剁椒土豆白菜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["湘菜", "香辣", "咸鲜", "爽脆"]', '["湘菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 2, "ingredientName": "菠菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["土豆去皮切薄片，浸入清水防氧化；白菜择洗干净，菜帮切斜片、菜叶切大段；洋葱切丝；胡萝卜切细丝；菠菜择净备用", "热锅宽油，下洋葱丝爆香至微焦黄，加1勺湖南剁椒、蒜末炝出红油", "转中火下土豆片煸炒2分钟至边缘微透明，加入胡萝卜丝、白菜帮翻炒1分钟", "放入白菜叶、菠菜，淋1勺生抽、半勺香醋，旺火快炒至断生", "撒少许白胡椒粉提味，装盘即可"]', '{"protein_estimate": 10.7, "calories_estimate": 299.0}', '{"douyin": "https://www.douyin.com/search/%E6%B9%98%E5%91%B3%E5%89%81%E6%A4%92%E5%9C%9F%E8%B1%86%E7%99%BD%E8%8F%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 14:25:47'),
	(25, '美式洋葱炖牛肉', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "咸鲜微甜", "慢炖软嫩", "高蛋白"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉切2cm方块，用厨房纸吸干表面水分；洋葱切厚片，胡萝卜切滚刀块，土豆去皮切大块（保留部分皮以减少营养流失）", "中火加热厚底锅，倒入15ml橄榄油，油热后单层码放牛肉块，每面煎2–3分钟至深褐色，取出备用（不加花生类调料）", "锅中留底油，转中小火，下洋葱片煸炒5分钟至透明微焦，加入胡萝卜、土豆翻炒3分钟", "将煎好的牛肉回锅，倒入400ml低钠牛肉高汤（或清水+1小勺无花生酱料粉），没过食材，加1茶匙番茄酱、1/4茶匙黑胡椒、少许海盐（不加花生酱、不含花生成分的调味品）", "大火烧开后撇净浮沫，转最小火加盖焖炖45分钟，期间翻动1次，确保均匀受热", "开盖转中火收汁8–10分钟，至汤汁浓稠裹肉，尝味微调盐量（避免过咸）", "装盘，可搭配少量蒸红薯增加饱腹感与膳食纤维，无需额外酱料"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E6%B4%8B%E8%91%B1%E7%82%96%E7%89%9B%E8%82%89+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 14:31:06'),
	(26, '美式牛肉土豆煎饼', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "咸香", "煎制", "高蛋白"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["将土豆和红薯去皮擦成细丝，用厨房纸吸干多余水分；洋葱切细末，与土豆丝、红薯丝混合，加入1个鸡蛋、1/4茶匙黑胡椒、1/4茶匙海盐拌匀。", "平底锅中火加热适量橄榄油（避开花生油），取约1/3杯混合物压成圆饼状放入锅中。", "中火煎4–5分钟至底部金黄定型，翻面再煎4分钟至两面酥脆、内部熟透。", "另起小锅，中火煸炒牛肉末（可用绞肉替代）2分钟至变色，加入少许洋葱末、胡萝卜碎（切细丁）同炒2分钟，加1/8茶匙烟熏红椒粉（可选）提味，不加酱料保持原味纯正。", "将煎好的土豆红薯饼盛盘，顶部铺上热牛肉馅，搭配薄片黄瓜和生白菜丝增爽口。", "撒少许新鲜黑胡椒与胡萝卜丝装饰，不额外添加花生类调料或酱汁。", "全程控制总耗时约22分钟，适配早餐快节奏，充分利用全部可用根茎类与蔬菜，零浪费。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E7%89%9B%E8%82%89%E5%9C%9F%E8%B1%86%E7%85%8E%E9%A5%BC+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 14:36:37'),
	(27, '美式黑椒牛肉红薯碗', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议瘦牛里脊或牛腱去脂切条）200g用1/4 tsp黑胡椒、1/8 tsp蒜粉、少许盐和5g橄榄油腌制10分钟。", "红薯150g去皮切滚刀块，蒸15分钟至软糯但不塌陷；同时将洋葱1/4个切丝、胡萝卜1/3根切细丝、白菜3片切宽条备用。", "中火加热不粘锅，倒入5g橄榄油，下牛肉条快速翻炒至表面焦褐（约90秒），盛出备用。", "原锅加少许水（非油），下洋葱丝与胡萝卜丝中火煸炒2分钟至微软，再加入白菜条大火翻炒1分钟至断生。", "将牛肉回锅，撒入现磨黑胡椒1/2 tsp和低钠酱油5ml，翻炒均匀，关火前淋入柠檬汁3滴提鲜。", "将蒸熟红薯块铺底，码上黑椒牛肉与蔬菜，可选点缀黄瓜薄片（生食，不加热）增脆感与水分。", "装盘即食，全程控油控盐，总耗时约25分钟，蛋白质≥32g，脂肪≤12g，碳水以低GI红薯为主。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E9%BB%91%E6%A4%92%E7%89%9B%E8%82%89%E7%BA%A2%E8%96%AF%E7%A2%97+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 14:45:15'),
	(28, '美式黑椒牛肉红薯碗', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议选用瘦牛里脊或牛腱去脂切条）200g用1/4 tsp黑胡椒粉、1/8 tsp蒜粉、少许盐和5g橄榄油腌制10分钟。", "红薯150g去皮切滚刀块，蒸12分钟至软糯但不散，取出稍压松散备用。", "中火加热不粘锅，倒入5g橄榄油，下洋葱丁60g煸炒2分钟至半透明。", "转大火，下腌好牛肉快速翻炒3–4分钟至表面焦褐、内部无粉红（中心温度达71℃），盛出备用。", "同一锅中加白菜丝80g、胡萝卜丝50g，中火快炒2分钟至断生仍脆嫩。", "将牛肉、红薯块回锅，淋入1 tsp低钠酱油+1/2 tsp现磨黑胡椒碎，翻拌均匀，关火焖1分钟。", "装盘，顶部点缀黄瓜薄片10g（生食增脆感），不额外添加花生或含花生酱调料。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E9%BB%91%E6%A4%92%E7%89%9B%E8%82%89%E7%BA%A2%E8%96%AF%E7%A2%97+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 14:59:51'),
	(29, '美式黑椒牛肉红薯碗', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议瘦牛里脊或牛腱去脂切条）200g用1/4 tsp黑胡椒、1/8 tsp蒜粉、少许盐和5g橄榄油腌制10分钟。", "红薯150g去皮切滚刀块，蒸15分钟至软糯但不塌陷；同时将洋葱1/4个切丝、胡萝卜1/3根切细丝、白菜叶撕成适口片。", "中火加热不粘锅，倒入5g橄榄油，下牛肉条快速翻炒至表面焦褐（约90秒/面），盛出备用。", "同一锅留底油，下洋葱丝和胡萝卜丝中火煸炒2分钟至微软，加入白菜片大火翻炒1分钟至断生。", "将牛肉回锅，撒入现磨黑胡椒1/2 tsp和低钠酱油5ml，快速翻匀（30秒），避免过咸。", "将蒸好的红薯块铺于碗底， topped with牛肉蔬菜混合物，淋上柠檬汁半茶匙提鲜解腻。", "可选：顶部点缀黄瓜薄片增脆感，不加花生类酱料或装饰，确保无花生过敏风险。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E9%BB%91%E6%A4%92%E7%89%9B%E8%82%89%E7%BA%A2%E8%96%AF%E7%A2%97+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 15:03:33'),
	(30, '黑椒瘦牛肉配烤蔬菜', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议用牛里脊或瘦牛腩，260g）逆纹切薄片，用1/4 tsp 黑胡椒粉、1/8 tsp 盐、1 tsp 低钠酱油、1 tsp 柠檬汁腌制15分钟；同时将洋葱切丝、胡萝卜切条、红薯切滚刀块（各约80g），茄子切厚片（80g），白菜掰成大片备用", "烤盘铺烘焙纸，将红薯块、胡萝卜条、茄子片平铺，淋半茶匙橄榄油，撒少许黑胡椒和盐，200°C空气炸锅/烤箱烤20分钟至边缘微焦、红薯软糯", "中火加热不粘锅，喷少量橄榄油，下腌好的牛肉片快速翻炒——每面30秒，至表面变褐但中心仍嫩（约2分钟总时长），盛出备用；避免久炒导致柴硬", "锅中补微量油，下洋葱丝中火煸炒2分钟至透明微甜，加入白菜大片翻炒1.5分钟至刚断生、保持脆感", "将烤蔬菜、炒洋葱白菜与牛肉片回锅，淋入1 tsp 低钠酱油+1/2 tsp 黑胡椒碎+1 tsp 柠檬汁，大火快拌30秒提香锁汁", "关火后静置1分钟让余温融合风味，装盘时以烤红薯块垫底，上覆牛肉与蔬菜，可撒少许新鲜黑胡椒碎增香", "全程控盐控油，无花生及衍生原料，蛋白质总量≥32g，总热量约360kcal，碳水主要来自低GI红薯与纤维丰富的蔬菜"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E9%BB%91%E6%A4%92%E7%98%A6%E7%89%9B%E8%82%89%E9%85%8D%E7%83%A4%E8%94%AC%E8%8F%9C+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 15:06:41'),
	(31, '川味凉拌牛肉丝', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["川菜", "麻辣鲜香", "冷拌少油", "高蛋白减脂"]', '["川菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["选用瘦牛里脊200g，冷冻15分钟稍硬后逆纹切极细丝（约0.1cm粗），用1/4 tsp 盐、1/2 tsp 料酒、1 tsp 蛋清、1 tsp 玉米淀粉抓匀腌制10分钟", "烧一锅水至微沸（约90℃），下牛肉丝快速滑散，焯烫45秒至变色即捞出，浸入冰水中冷却，沥干备用（确保嫩而不柴）", "白菜取嫩叶部分150g切细丝；黄瓜100g拍松切粗丝；胡萝卜80g切细丝；洋葱50g切细丝；全部蔬菜丝加少许盐（1/8 tsp）轻揉1分钟，静置5分钟杀出水分，挤干", "调拌汁：2 tsp 生抽、1 tsp 香醋、1/2 tsp 蒜末、1/4 tsp 姜末、1/4 tsp 辣椒油（无花生成分）、1/8 tsp 花椒粉、3滴香油、少许白芝麻（确认无花生污染），搅匀", "将牛肉丝与蔬菜丝混合，淋入拌汁，顺一个方向轻拌30秒至均匀入味", "装盘后撒少许新鲜香菜碎（如用户不忌口）或葱花，冷藏静置8分钟更爽口", "食用前轻拌一次，确保风味融合，温度控制在10–15℃最佳"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E5%B7%9D%E5%91%B3%E5%87%89%E6%8B%8C%E7%89%9B%E8%82%89%E4%B8%9D+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 15:10:31'),
	(32, '美式牛肉土豆煎饼', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "咸香酥脆", "煎制", "高蛋白"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["将土豆和红薯去皮擦成细丝，用纱布挤干水分；洋葱切碎；胡萝卜擦丝；所有蔬菜混合备用。", "取200g瘦牛肉末（假设用户可获取，符合美式牛肉菜系核心），加入1/4茶匙黑胡椒、1/8茶匙海盐、1小勺橄榄油，与蔬菜混合均匀，静置5分钟入味。", "平底锅中火预热，刷薄层油；取约1/3杯混合肉蔬糊压成圆饼状（厚约1cm），放入锅中。", "中火煎4分钟至底部金黄定型，翻面再煎4分钟，全程保持中小火避免焦糊，确保牛肉全熟（中心温度达71°C）。", "出锅前30秒撒少许葱花（若无过敏）或省略；无需额外酱料，保留原汁牛肉香与薯类甜糯。", "搭配黄瓜片和少量白菜丝清口解腻，即食。", "剩余糊糊可冷藏保存24小时，避免重复加热，减少食材浪费。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E7%89%9B%E8%82%89%E5%9C%9F%E8%B1%86%E7%85%8E%E9%A5%BC+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 15:13:28'),
	(33, '川味凉拌黄瓜茄子', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["川菜", "麻辣爽口", "凉拌免炒", "低脂高纤"]', '["川菜"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["黄瓜、茄子洗净；黄瓜拍松切段，茄子去皮切长条（约5cm），用少量盐腌10分钟，挤干水分备用。", "锅中烧水至沸腾，下茄子条焯水90秒至断生（保持脆嫩），捞出迅速浸冰水，沥干。", "小碗中调制川味凉汁：2勺生抽、1勺香醋、1/2勺花椒油、1/4勺辣椒油（确保无花生成分）、少许蒜末、少许糖、几粒熟白芝麻，搅匀。", "将黄瓜段、茄子条、薄片洋葱（适量）放入大碗，淋入凉汁，撒少许香菜碎（可选）。", "轻拌均匀，静置腌渍5分钟使入味。", "装盘前滴2滴香油增亮，再撒少许小米辣圈（可选，依辣度调整）。", "冷藏10分钟更爽口，适合作为午间减脂主菜上桌。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E5%B7%9D%E5%91%B3%E5%87%89%E6%8B%8C%E9%BB%84%E7%93%9C%E8%8C%84%E5%AD%90+%E6%95%99%E7%A8%8B", "imageUrl": "/recipe-images/recipe-33-1774164100695.png"}', 1, '2026-03-22 15:21:16'),
	(34, '美式黑椒牛肉红薯碗', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议用瘦牛里脊或牛腱去脂切条）200g，用1/4 tsp黑胡椒粉、1/8 tsp蒜粉、少许盐、5g橄榄油腌制10分钟。", "红薯150g去皮切滚刀块，蒸15分钟至软糯但不塌陷；土豆100g切薄片焯水2分钟沥干备用。", "热锅喷少量油（约3g），中高火将牛肉条快速翻炒至表面焦褐（约90秒/面），盛出备用。", "锅中补3g油，下洋葱丁50g、胡萝卜丝60g、白菜帮60g大火煸炒2分钟至断生微甜。", "倒入炒好的牛肉、蒸好的红薯块、焯水土豆片，加1 tsp低钠酱油、1/2 tsp现磨黑胡椒、1小勺柠檬汁，中火翻炒均匀1分钟。", "关火前撒入黄瓜片40g（生食，最后加入保持脆爽），轻拌匀。", "装盘，可选点缀少许新鲜欧芹碎——全程无花生及衍生原料，符合减脂高蛋白午餐需求。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E9%BB%91%E6%A4%92%E7%89%9B%E8%82%89%E7%BA%A2%E8%96%AF%E7%A2%97+%E6%95%99%E7%A8%8B", "imageUrl": "/recipe-images/default-dish.svg"}', 1, '2026-03-22 15:34:12'),
	(35, '美式黑椒牛肉红薯碗', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议用瘦牛里脊或牛腱去脂切条）200g用1/4 tsp黑胡椒粉、1/8 tsp蒜粉、1/8 tsp洋葱粉、少许盐腌制10分钟；红薯150g去皮切滚刀块，微波高火4分钟至半熟（或蒸5分钟），备用。", "中火加热不粘锅，喷少量橄榄油，下牛肉条快速翻炒至表面变色（约90秒），盛出备用，避免过熟变柴。", "同一锅中补喷少许油，下洋葱丁1/4个（约60g）中火煸香至透明（2分钟），加入胡萝卜片60g、白菜帮60g（切细条）翻炒1分钟至断生。", "倒入半熟红薯块、炒过的牛肉条，淋入1 tsp低钠酱油、1/2 tsp现磨黑胡椒碎、1 tsp柠檬汁，中大火翻炒均匀（1分30秒），使酱汁裹匀食材。", "关火前撒黄瓜片30g（生食，最后加入保持脆爽）、少许新鲜欧芹碎（可选），轻轻拌匀。", "装入深盘或碗中，顶部可点缀几片薄黄瓜增加清新感，无需额外主食即可满足午餐饱腹与营养需求。", "全程耗时约22分钟，总热量约385kcal，蛋白质≥32g，脂肪≤12g，碳水≈38g（以复合碳水为主）。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E9%BB%91%E6%A4%92%E7%89%9B%E8%82%89%E7%BA%A2%E8%96%AF%E7%A2%97+%E6%95%99%E7%A8%8B", "imageUrl": "/recipe-images/default-dish.svg"}', 1, '2026-03-22 15:42:09'),
	(36, '美式洋葱炖牛肉', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "咸鲜微甜", "慢炖软嫩", "高蛋白"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉切2cm见方块，用厨房纸吸干表面水分；洋葱切粗丝，胡萝卜、土豆去皮切滚刀块。", "中火加热厚底锅，不放油，将牛肉块单层铺入锅中，煎至各面焦黄（约2分钟/面），盛出备用。", "锅中留底油（如无则加1小勺橄榄油），下洋葱丝中火煸炒5分钟至透明微焦，加入胡萝卜、土豆块翻炒3分钟。", "将煎好的牛肉倒回锅中，加清水没过食材2cm，滴入1勺酱油（不含花生成分）、少许黑胡椒和海盐，大火烧沸后转最小火加盖焖炖25分钟。", "开盖检查牛肉软烂程度，若汤汁过多可中火收至浓稠（约3分钟），尝味微调咸淡。", "关火前撒新鲜葱花（可选），静置2分钟让风味融合。", "盛入深盘，搭配少量红薯块同煮增饱腹感（红薯切块与牛肉同炖最后10分钟加入）"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E6%B4%8B%E8%91%B1%E7%82%96%E7%89%9B%E8%82%89+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 15:48:26'),
	(37, '美式洋葱炖牛肉', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "咸鲜微甜", "慢炖软嫩", "高蛋白"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉切2cm见方块，用厨房纸吸干表面水分；洋葱切粗丝，胡萝卜、土豆去皮切滚刀块。", "中火加热厚底锅，不放油，将牛肉块单层铺入锅中，煎至各面焦黄（约2分钟/面），盛出备用。", "锅中留底油（如无则加1小勺橄榄油），下洋葱丝中火煸炒5分钟至透明微焦，加入胡萝卜和土豆块翻炒3分钟。", "倒回牛肉，加足量热水没过食材，滴入1勺酱油、1/4茶匙黑胡椒粉，大火烧开后转最小火加盖焖炖25分钟。", "开盖检查牛肉已软嫩，汤汁收至浓稠（若过多可中火收汁3分钟），尝味补少许盐（慎加，酱油已有咸度）。", "关火前撒少量新鲜葱花（可选），静置2分钟让风味融合。", "盛入深盘，搭配红薯块同煮（可于步骤3时与土豆同入锅）或单独蒸熟作配餐。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E6%B4%8B%E8%91%B1%E7%82%96%E7%89%9B%E8%82%89+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 15:57:53'),
	(38, '美式黑椒牛肉红薯碗', '基于时段、个人画像与历史偏好生成，食材严格来自字典库。', 1, '["美式牛肉", "高蛋白", "黑椒风味", "少油快炒"]', '["美式牛肉"]', 25, 0, '[{"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 1, "ingredientName": "白菜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 12, "ingredientName": "洋葱"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 14, "ingredientName": "黄瓜"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 15, "ingredientName": "茄子"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 18, "ingredientName": "土豆"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 19, "ingredientName": "红薯"}, {"unit": "g", "quantity": 120.0, "categoryId": 1, "ingredientId": 21, "ingredientName": "胡萝卜"}]', '["牛肉（建议用瘦牛里脊或牛腱去脂切条）200g，用1/4 tsp黑胡椒粉、1/8 tsp蒜粉、少许盐、5g橄榄油腌制10分钟。", "红薯150g去皮切滚刀块，蒸15分钟至软糯但不塌陷；土豆100g切薄片焯水2分钟沥干备用。", "热锅喷少量油（约3g），中高火将牛肉条快速翻炒至表面焦褐（约90秒/面），盛出备用。", "锅中补3g油，下洋葱丁50g、胡萝卜丝60g、白菜帮60g大火煸炒2分钟至断生微甜。", "倒入炒好的牛肉、蒸好的红薯块、焯水土豆片，加1 tsp低钠酱油、1/2 tsp现磨黑胡椒、1小勺柠檬汁，中火翻炒均匀1分钟。", "关火前撒黄瓜片30g（生食，保留脆感与水分），轻拌匀。", "装盘，顶部可点缀少许新鲜欧芹（如无则省略），不额外添加酱料或坚果。"]', '{"protein_estimate": 8.8, "calories_estimate": 301.0}', '{"douyin": "https://www.douyin.com/search/%E7%BE%8E%E5%BC%8F%E9%BB%91%E6%A4%92%E7%89%9B%E8%82%89%E7%BA%A2%E8%96%AF%E7%A2%97+%E6%95%99%E7%A8%8B"}', 1, '2026-03-22 16:04:38');
